## 1. Basic HTML Button

```html
<button onclick="alert('Button clicked!')">Click Me</button>
```

## 2. Styled CSS Button

```html
<!DOCTYPE html>
<html>
<head>
<style>
  .my-btn {
    background-color: #4CAF50;
    color: white;
    padding: 12px 24px;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 16px;
    transition: background-color 0.3s;
  }
  .my-btn:hover {
    background-color: #45a049;
  }
</style>
</head>
<body>
  <button class="my-btn">Click Me</button>
</body>
</html>
```

## 3. React Button (with onClick)

```jsx
import React, { useState } from 'react';

function MyButton() {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    setCount(count + 1);
    console.log('Clicked! Count:', count + 1);
  };

  return (
    <button onClick={handleClick}>
      Clicked {count} times
    </button>
  );
}

export default MyButton;
```

## 4. React Native Button

```jsx
import React from 'react';
import { Button, View, Alert } from 'react-native';

const App = () => {
  return (
    <View>
      <Button
        title="Press Me"
        onPress={() => Alert.alert('Button Pressed!')}
        color="#841584"
      />
    </View>
  );
};

export default App;
```

## 5. Vue.js Button

```vue
<template>
  <button @click="handleClick" class="my-btn">
    {{ count }} Clicks
  </button>
</template>

<script>
export default {
  data() {
    return { count: 0 };
  },
  methods: {
    handleClick() {
      this.count++;
    }
  }
}
</script>
```

